  --line: rgba(255, 255, 255, 0.14);
  --muted: rgba(220, 232, 236, 0.58);
  --mono: "SFMono-Regular", "Cascadia Mono", "Roboto Mono", "Consolas", monospace;
  --display: "Bahnschrift", "DIN Alternate", "Arial Narrow", "Franklin Gothic Medium", Impact, sans-serif;
}

* { box-sizing: border-box; }
html, body { width: 100%; height: 100%; margin: 0; overflow: hidden; background: #050708; }
body {
  font-family: var(--display);
  color: #eef5f7;
  -webkit-font-smoothing: antialiased;
  user-select: none;
}
#app { position: fixed; inset: 0; overflow: hidden; background: #050708; }
#game { position: absolute; inset: 0; width: 100%; height: 100%; display: block; outline: none; }
.hidden { display: none !important; }

/* ---------- shared screen chrome ---------- */
.screen { position: absolute; inset: 0; z-index: 50; }
.start-screen {
  background:
    linear-gradient(90deg, rgba(4,7,9,0.93) 0%, rgba(4,7,9,0.78) 38%, rgba(4,7,9,0.26) 68%, rgba(4,7,9,0.55) 100%),
    radial-gradient(ellipse at 72% 48%, rgba(255,106,26,0.11), transparent 42%),
    linear-gradient(0deg, rgba(4,7,9,0.98), transparent 44%);
  display: flex;
  flex-direction: column;
  padding: 32px 44px 26px;
}
.menu-vignette {
  position: absolute; inset: 0; pointer-events: none;
  box-shadow: inset 0 0 240px 60px rgba(0,0,0,0.85);
  background: repeating-linear-gradient(0deg, rgba(255,255,255,0.018) 0 1px, transparent 1px 4px);
  mix-blend-mode: overlay;
}
.menu-grid {
  position: absolute; inset: 0; pointer-events: none; opacity: 0.18;
  background-image:
    linear-gradient(rgba(122,232,255,0.2) 1px, transparent 1px),
    linear-gradient(90deg, rgba(122,232,255,0.2) 1px, transparent 1px);
  background-size: 88px 88px;
  mask-image: radial-gradient(ellipse at 70% 45%, black, transparent 66%);
}
.menu-top { position: relative; display: flex; align-items: center; gap: 20px; z-index: 2; }
.logo-mark { display: flex; align-items: flex-end; gap: 3px; height: 26px; }
.logo-mark span { display: block; width: 6px; background: var(--orange); box-shadow: 0 0 14px rgba(255,106,26,0.6); }
.logo-mark span:nth-child(1) { height: 13px; opacity: 0.55; }
.logo-mark span:nth-child(2) { height: 21px; }
.logo-mark span:nth-child(3) { height: 26px; opacity: 0.8; }
.studio { font-size: 12px; letter-spacing: 0.3em; color: rgba(235,245,248,0.62); }
.studio b { color: #fff; font-weight: 700; }
.classification { margin-left: auto; font-family: var(--mono); font-size: 9px; letter-spacing: 0.18em; color: rgba(255,106,26,0.75); border: 1px solid rgba(255,106,26,0.28); padding: 6px 10px; }

.menu-main { position: relative; z-index: 2; margin-top: auto; margin-bottom: auto; max-width: 730px; padding-left: 2.8vw; }
.eyebrow { font-family: var(--mono); font-size: 11px; letter-spacing: 0.38em; color: var(--orange); display: flex; align-items: center; gap: 12px; margin-bottom: 18px; }
.eyebrow::before { content: ""; width: 34px; height: 1px; background: var(--orange); box-shadow: 0 0 10px var(--orange); }
.eyebrow span { color: rgba(238,245,247,0.7); }
h1 {
  margin: 0;
  font-size: clamp(64px, 8.4vw, 132px);
  line-height: 0.82;
  letter-spacing: -0.035em;
  font-weight: 800;
  text-transform: uppercase;
  text-shadow: 0 6px 40px rgba(0,0,0,0.55);
}
h1 span { color: var(--orange); text-shadow: 0 0 30px rgba(255,106,26,0.5); }
h1 em { font-style: normal; color: transparent; -webkit-text-stroke: 1.5px rgba(238,245,247,0.62); letter-spacing: 0.01em; }
.tagline { margin: 26px 0 0; max-width: 570px; font-family: var(--mono); font-size: 12px; line-height: 1.85; color: rgba(224,236,240,0.62); letter-spacing: 0.01em; }
.menu-actions { display: flex; align-items: center; gap: 18px; margin-top: 34px; }

.deploy-button {
  position: relative;
  border: 0;
  padding: 0;
  width: 260px;
  height: 62px;
  background: linear-gradient(100deg, #ff6a1a, #ff8b3d 58%, #ffb066);
  color: #0b0d0d;
  font-family: var(--display);
  font-size: 17px;
  font-weight: 800;
  letter-spacing: 0.22em;
  cursor: pointer;
  clip-path: polygon(0 0, 100% 0, 100% 72%, calc(100% - 16px) 100%, 0 100%);
  transition: transform 0.12s ease, filter 0.12s ease;
  box-shadow: 0 0 34px rgba(255,106,26,0.28);
}
.deploy-button span { position: relative; z-index: 2; }
.deploy-button i {
  position: absolute; inset: 2px; background: linear-gradient(100deg, rgba(255,255,255,0.35), transparent 40%);
  clip-path: polygon(0 0, 100% 0, 100% 72%, calc(100% - 16px) 100%, 0 100%);
  opacity: 0.55;
}
.deploy-button:hover { transform: translateY(-2px); filter: brightness(1.1); }
.deploy-button:active { transform: translateY(0) scale(0.99); }
.ghost-button {
  height: 62px; padding: 0 26px; background: rgba(8,12,14,0.42); color: rgba(238,245,247,0.8);
  border: 1px solid rgba(255,255,255,0.18); font-family: var(--mono); font-size: 10px; letter-spacing: 0.2em;
  cursor: pointer; backdrop-filter: blur(8px); transition: all 0.15s ease;
}
.ghost-button:hover { border-color: var(--orange); color: #fff; background: rgba(255,106,26,0.1); }
.menu-stats { display: flex; gap: 54px; margin-top: 44px; }
.menu-stats div { display: flex; flex-direction: column; gap: 3px; }
.menu-stats b { font-size: 24px; color: #fff; letter-spacing: 0.04em; }
.menu-stats span { font-family: var(--mono); font-size: 8px; letter-spacing: 0.24em; color: rgba(220,232,236,0.45); }

.brief-panel {
  position: absolute; z-index: 3; right: 44px; top: 50%; transform: translateY(-46%);
  width: 292px; background: linear-gradient(160deg, rgba(9,14,17,0.82), rgba(5,8,10,0.62));
  border: 1px solid rgba(255,255,255,0.12); border-top: 2px solid var(--orange);
  padding: 18px 20px 20px; backdrop-filter: blur(12px);
  box-shadow: 0 26px 70px rgba(0,0,0,0.45);
}
.brief-header { display: flex; justify-content: space-between; align-items: center; font-family: var(--mono); font-size: 9px; letter-spacing: 0.2em; color: var(--orange); padding-bottom: 12px; border-bottom: 1px solid rgba(255,255,255,0.1); }
.brief-header b { font-family: var(--display); font-size: 30px; color: rgba(255,255,255,0.12); letter-spacing: 0; }
.brief-row { display: flex; justify-content: space-between; gap: 12px; padding: 12px 0; border-bottom: 1px solid rgba(255,255,255,0.065); font-family: var(--mono); font-size: 9px; letter-spacing: 0.09em; }
.brief-row span { color: rgba(220,232,236,0.42); }
.brief-row strong { color: rgba(238,245,247,0.9); font-weight: 600; text-align: right; }
.brief-row .danger { color: var(--red); }
.brief-note { margin-top: 15px; font-family: var(--mono); font-size: 9px; line-height: 1.75; color: rgba(220,232,236,0.4); }
.menu-footer { position: relative; z-index: 2; display: flex; align-items: flex-end; justify-content: space-between; gap: 30px; }
.controls-grid { display: flex; flex-wrap: wrap; gap: 8px 22px; max-width: 760px; }
.controls-grid span { font-family: var(--mono); font-size: 8px; color: rgba(220,232,236,0.44); letter-spacing: 0.12em; }
.controls-grid b { color: rgba(238,245,247,0.82); font-weight: 600; margin-right: 3px; }
.audio-note { font-family: var(--mono); font-size: 8px; letter-spacing: 0.16em; color: rgba(220,232,236,0.35); white-space: nowrap; }
.pulse { display: inline-block; width: 5px; height: 5px; border-radius: 50%; background: var(--orange); margin-right: 7px; box-shadow: 0 0 9px var(--orange); animation: pulse 1.6s infinite; }
@keyframes pulse { 0%,100% { opacity: 1; } 50% { opacity: 0.25; } }

.brief-modal { position: absolute; inset: 0; z-index: 8; background: rgba(2,4,5,0.72); backdrop-filter: blur(10px); display: flex; align-items: center; justify-content: center; }
.brief-modal-inner { width: min(620px, 86vw); background: linear-gradient(160deg, #12191d, #080c0e); border: 1px solid rgba(255,255,255,0.13); border-top: 2px solid var(--orange); padding: 34px 38px; box-shadow: 0 30px 100px #000; }
.brief-modal-kicker { font-family: var(--mono); font-size: 9px; letter-spacing: 0.25em; color: var(--orange); }
.brief-modal h2 { font-size: 46px; margin: 10px 0 16px; letter-spacing: -0.02em; }
.brief-modal p { font-family: var(--mono); font-size: 12px; line-height: 1.8; color: rgba(220,232,236,0.6); }
.brief-modal ul { list-style: none; padding: 0; margin: 20px 0 26px; display: grid; gap: 10px; }
.brief-modal li { font-family: var(--mono); font-size: 10px; line-height: 1.65; color: rgba(220,232,236,0.6); border-left: 1px solid rgba(255,106,26,0.4); padding-left: 12px; }
.brief-modal li b { color: var(--orange); margin-right: 8px; }

/* ---------- HUD ---------- */
#hud { position: absolute; inset: 0; z-index: 20; pointer-events: none; }
.hud-grain { position: absolute; inset: 0; opacity: 0.05; background-image: url("data:image/svg+xml,%3Csvg viewBox='0 0 160 160' xmlns='http://www.w3.org/2000/svg'%3E%3Cfilter id='n'%3E%3CfeTurbulence type='fractalNoise' baseFrequency='0.9' numOctaves='2' stitchTiles='stitch'/%3E%3C/filter%3E%3Crect width='100%25' height='100%25' filter='url(%23n)' opacity='0.55'/%3E%3C/svg%3E"); mix-blend-mode: overlay; }
.hud-scan { position: absolute; inset: 0; background: repeating-linear-gradient(0deg, rgba(255,255,255,0.012) 0 1px, transparent 1px 3px); opacity: 0.5; }
#damageVignette { position: absolute; inset: 0; background: radial-gradient(ellipse at center, transparent 40%, rgba(255,15,35,0.45) 100%); opacity: 0; transition: opacity 0.12s; }
#lowHealth { position: absolute; inset: 0; background: radial-gradient(ellipse at center, transparent 45%, rgba(130,0,8,0.42) 100%); opacity: 0; transition: opacity 0.4s; animation: lowPulse 1.4s infinite; }
@keyframes lowPulse { 0%,100% { filter: brightness(0.8); } 50% { filter: brightness(1.3); } }

.panel {
  background: linear-gradient(145deg, rgba(8,13,16,0.78), rgba(5,8,10,0.5));
  border: 1px solid rgba(255,255,255,0.12);
  backdrop-filter: blur(8px);
  box-shadow: 0 10px 38px rgba(0,0,0,0.24);
}
.mission { position: absolute; left: 30px; top: 26px; width: 314px; padding: 13px 16px 12px; clip-path: polygon(0 0, 100% 0, 100% calc(100% - 12px), calc(100% - 12px) 100%, 0 100%); border-left: 2px solid var(--orange); }
.mission-top { display: flex; align-items: center; gap: 8px; font-family: var(--mono); font-size: 8px; letter-spacing: 0.16em; color: rgba(220,232,236,0.55); }
.live-dot { width: 5px; height: 5px; background: var(--red); border-radius: 50%; box-shadow: 0 0 8px var(--red); animation: pulse 1.2s infinite; }
.clock { margin-left: auto; color: rgba(238,245,247,0.75); }
.objective-label { margin-top: 12px; font-family: var(--mono); font-size: 7px; letter-spacing: 0.3em; color: var(--orange); }
.objective-text { margin-top: 4px; font-size: 18px; letter-spacing: 0.1em; font-weight: 700; color: #fff; }
.wave-row { display: flex; justify-content: space-between; margin-top: 11px; font-family: var(--mono); font-size: 8px; letter-spacing: 0.12em; color: rgba(220,232,236,0.52); }
.wave-track { height: 2px; margin-top: 7px; background: rgba(255,255,255,0.12); overflow: hidden; }
#waveProgress { height: 100%; width: 0%; background: linear-gradient(90deg, var(--orange), var(--orange-hot)); box-shadow: 0 0 10px var(--orange); transition: width 0.5s ease; }

.compass-wrap { position: absolute; top: 22px; left: 50%; transform: translateX(-50%); width: min(440px, 38vw); display: flex; justify-content: center; }
#compass { width: 100%; height: auto; filter: drop-shadow(0 4px 16px rgba(0,0,0,0.4)); }
.compass-center { position: absolute; top: 0; width: 1px; height: 12px; background: var(--orange); box-shadow: 0 0 10px var(--orange); }

.top-right { position: absolute; right: 28px; top: 24px; width: 268px; display: flex; flex-direction: column; align-items: flex-end; gap: 10px; }
.score-panel { display: flex; width: 100%; padding: 9px 12px; gap: 0; justify-content: space-between; clip-path: polygon(10px 0, 100% 0, 100% 100%, 0 100%, 0 10px); }
.score-item { display: flex; flex-direction: column; gap: 1px; }
.score-item span { font-family: var(--mono); font-size: 7px; letter-spacing: 0.2em; color: rgba(220,232,236,0.4); }
.score-item strong { font-family: var(--mono); font-size: 13px; color: #fff; letter-spacing: 0.04em; }
.score-item:first-child strong { color: var(--orange); }
.radar-panel { position: relative; width: 164px; height: 164px; padding: 8px; border-radius: 50%; overflow: hidden; background: radial-gradient(circle, rgba(15,29,33,0.85), rgba(5,9,11,0.62)); }
#radar { width: 100%; height: 100%; display: block; }
.radar-label { position: absolute; bottom: 9px; left: 0; right: 0; text-align: center; font-family: var(--mono); font-size: 6px; letter-spacing: 0.18em; color: rgba(122,232,255,0.55); }
.kill-feed { width: 100%; display: flex; flex-direction: column; align-items: flex-end; gap: 4px; margin-top: 2px; }
.feed-item { font-family: var(--mono); font-size: 8px; letter-spacing: 0.08em; color: rgba(238,245,247,0.72); background: rgba(5,9,11,0.62); border-right: 2px solid rgba(255,255,255,0.3); padding: 4px 8px; animation: feedIn 0.18s ease-out; }
.feed-item b { color: var(--orange); }
.feed-item .hs { color: var(--red); }
@keyframes feedIn { from { opacity: 0; transform: translateX(12px); } to { opacity: 1; transform: none; } }

.health-panel { position: absolute; left: 30px; bottom: 30px; width: 332px; padding: 11px 15px 12px; clip-path: polygon(0 0, 100% 0, 100% 100%, 14px 100%, 0 calc(100% - 14px)); border-left: 2px solid rgba(122,232,255,0.55); }
.callsign { font-family: var(--mono); font-size: 8px; letter-spacing: 0.18em; color: rgba(238,245,247,0.7); }
.callsign span { color: rgba(220,232,236,0.34); }
.health-line { display: flex; align-items: flex-end; gap: 13px; margin-top: 4px; }
.health-icon { font-family: var(--mono); font-size: 22px; line-height: 1; color: var(--cyan); opacity: 0.8; }
.health-main { display: flex; align-items: center; gap: 9px; }
.health-main strong { font-family: var(--mono); font-size: 34px; line-height: 1; font-weight: 600; letter-spacing: -0.06em; color: #fff; }
.health-main strong.low { color: var(--red); text-shadow: 0 0 18px rgba(255,48,69,0.5); }
.bar { height: 4px; background: rgba(255,255,255,0.14); overflow: hidden; }
.health-bar { width: 92px; }
#healthFill { height: 100%; width: 100%; background: linear-gradient(90deg, #37cfe8, #a5f6ff); box-shadow: 0 0 10px rgba(122,232,255,0.6); transition: width 0.18s; }
.armor-main { margin-left: auto; display: grid; grid-template-columns: auto auto; align-items: end; gap: 1px 8px; }
.armor-main span { font-family: var(--mono); font-size: 7px; letter-spacing: 0.18em; color: rgba(220,232,236,0.4); }
.armor-main strong { font-family: var(--mono); font-size: 15px; text-align: right; color: rgba(238,245,247,0.85); grid-row: 1 / 3; grid-column: 2; }
.armor-bar { width: 62px; grid-column: 1; }
#armorFill { height: 100%; width: 100%; background: linear-gradient(90deg, #ff6a1a, #ffcf9e); box-shadow: 0 0 10px rgba(255,106,26,0.45); transition: width 0.18s; }

.ammo-panel { position: absolute; right: 30px; bottom: 30px; width: 306px; padding: 10px 16px 11px; text-align: right; clip-path: polygon(0 0, 100% 0, 100% calc(100% - 14px), calc(100% - 14px) 100%, 0 100%); border-right: 2px solid var(--orange); }
.weapon-name { font-family: var(--mono); font-size: 8px; letter-spacing: 0.2em; color: rgba(220,232,236,0.55); }
.ammo-line { display: flex; justify-content: flex-end; align-items: baseline; gap: 7px; margin-top: -2px; }
.mag { font-family: var(--mono); font-size: 42px; line-height: 1; font-weight: 600; color: #fff; letter-spacing: -0.06em; }
.mag.empty { color: var(--red); }
.slash { font-family: var(--mono); font-size: 16px; color: rgba(220,232,236,0.25); }
.reserve { font-family: var(--mono); font-size: 15px; color: rgba(220,232,236,0.65); }
.ammo-meta { display: flex; justify-content: flex-end; gap: 13px; margin-top: 7px; font-family: var(--mono); font-size: 7px; letter-spacing: 0.15em; color: rgba(220,232,236,0.43); }
#reloadState { color: var(--orange); }

.loadout { position: absolute; left: 50%; bottom: 31px; transform: translateX(-50%); display: flex; gap: 5px; }
.slot { width: 74px; padding: 6px 8px; background: rgba(6,10,12,0.58); border: 1px solid rgba(255,255,255,0.1); display: flex; align-items: center; gap: 7px; font-family: var(--mono); font-size: 7px; letter-spacing: 0.1em; color: rgba(220,232,236,0.48); }
.slot b { display: inline-flex; align-items: center; justify-content: center; width: 16px; height: 16px; border: 1px solid rgba(255,255,255,0.18); font-size: 7px; color: rgba(238,245,247,0.7); }
.slot.active { border-color: rgba(255,106,26,0.55); color: #fff; background: rgba(255,106,26,0.09); }
.slot.active b { border-color: var(--orange); color: var(--orange); }

.reticle { position: absolute; left: 50%; top: 50%; width: 44px; height: 44px; transform: translate(-50%, -50%); }
.reticle i { position: absolute; background: rgba(255,255,255,0.9); box-shadow: 0 0 4px rgba(0,0,0,0.8); transition: all 0.08s; }
.r-top, .r-bottom { width: 1px; height: 8px; left: 21px; }
.r-left, .r-right { width: 8px; height: 1px; top: 21px; }
.r-top { top: 4px; } .r-bottom { bottom: 4px; } .r-left { left: 4px; } .r-right { right: 4px; }
.r-dot { position: absolute; left: 50%; top: 50%; width: 2px; height: 2px; transform: translate(-50%,-50%); background: var(--orange); border-radius: 50%; box-shadow: 0 0 5px var(--orange); }
.reticle.wide i { background: rgba(255,255,255,0.62); }
.reticle.ads i { opacity: 0.25; }
.reticle.ads .r-dot { width: 4px; height: 4px; background: var(--red); box-shadow: 0 0 7px var(--red); }

.hitmarker { position: absolute; inset: 0; opacity: 0; transform: scale(1.6); }
.hitmarker.show { animation: hitPop 0.22s ease-out; }
.hitmarker i { position: absolute; width: 8px; height: 2px; background: #fff; box-shadow: 0 0 6px #fff; left: 18px; top: 21px; }
.hitmarker i:nth-child(1) { transform: rotate(45deg) translate(8px, 0); }
.hitmarker i:nth-child(2) { transform: rotate(135deg) translate(8px, 0); }
.hitmarker i:nth-child(3) { transform: rotate(225deg) translate(8px, 0); }
.hitmarker i:nth-child(4) { transform: rotate(315deg) translate(8px, 0); }
.hitmarker.head i { background: var(--red); box-shadow: 0 0 8px var(--red); }
@keyframes hitPop { 0% { opacity: 1; transform: scale(1.7); } 100% { opacity: 0; transform: scale(1); } }

.damage-arrow { position: absolute; left: 21px; top: -24px; width: 2px; height: 15px; background: var(--red); opacity: 0; filter: drop-shadow(0 0 5px var(--red)); transform-origin: 50% 56px; }

.interact-prompt { position: absolute; left: 50%; top: calc(50% + 58px); transform: translateX(-50%); font-family: var(--mono); font-size: 9px; letter-spacing: 0.15em; color: rgba(238,245,247,0.8); background: rgba(5,9,11,0.7); border: 1px solid rgba(255,106,26,0.35); padding: 7px 12px; }
.interact-prompt b { color: var(--orange); }

.wave-banner { position: absolute; left: 50%; top: 31%; transform: translate(-50%, -50%); text-align: center; opacity: 0; pointer-events: none; }
.wave-banner.show { animation: bannerIn 4.2s ease forwards; }
.banner-kicker { font-family: var(--mono); font-size: 10px; letter-spacing: 0.5em; color: var(--orange); margin-bottom: 8px; }
.banner-title { font-family: var(--display); font-weight: 800; font-size: clamp(46px, 7vw, 92px); letter-spacing: 0.04em; line-height: 0.9; color: #fff; text-shadow: 0 0 60px rgba(255,106,26,0.3); }
.banner-sub { margin-top: 10px; font-family: var(--mono); font-size: 9px; letter-spacing: 0.28em; color: rgba(220,232,236,0.55); }
@keyframes bannerIn { 0% { opacity: 0; transform: translate(-50%,-50%) scale(1.08); } 12% { opacity: 1; transform: translate(-50%,-50%) scale(1); } 78% { opacity: 1; } 100% { opacity: 0; } }

.event-feed { position: absolute; left: 50%; bottom: 124px; transform: translateX(-50%); display: flex; flex-direction: column; align-items: center; gap: 5px; }
.event-line { font-family: var(--mono); font-size: 8px; letter-spacing: 0.14em; color: rgba(238,245,247,0.7); background: rgba(5,9,11,0.55); padding: 4px 10px; border-bottom: 1px solid rgba(255,106,26,0.4); animation: eventIn 0.2s ease-out; }
.event-line b { color: var(--orange); }
@keyframes eventIn { from { opacity: 0; transform: translateY(5px); } to { opacity: 1; } }

.xp-layer { position: absolute; inset: 0; overflow: hidden; }
.xp-pop { position: absolute; font-family: var(--mono); font-size: 11px; font-weight: 700; letter-spacing: 0.06em; color: var(--orange); text-shadow: 0 2px 12px #000; animation: xpFloat 1s ease-out forwards; white-space: nowrap; }
.xp-pop.head { color: var(--red); font-size: 13px; }
@keyframes xpFloat { 0% { opacity: 0; transform: translate(-50%, 0) scale(0.8); } 15% { opacity: 1; transform: translate(-50%, -8px) scale(1.05); } 100% { opacity: 0; transform: translate(-50%, -52px) scale(0.94); } }

.control-hint { position: absolute; left: 50%; bottom: 8px; transform: translateX(-50%); display: flex; gap: 14px; font-family: var(--mono); font-size: 6px; letter-spacing: 0.12em; color: rgba(220,232,236,0.3); white-space: nowrap; }
.control-hint b { color: rgba(238,245,247,0.55); margin-right: 2px; }
.build-tag { position: absolute; right: 32px; bottom: 7px; font-family: var(--mono); font-size: 6px; letter-spacing: 0.18em; color: rgba(220,232,236,0.22); }
.toast { position: absolute; left: 50%; top: 17%; transform: translateX(-50%); font-family: var(--mono); font-size: 9px; letter-spacing: 0.16em; color: var(--orange); background: rgba(5,9,11,0.65); padding: 6px 12px; border: 1px solid rgba(255,106,26,0.3); opacity: 0; transition: opacity 0.2s; }
.toast.show { opacity: 1; }

/* ---------- pause / end ---------- */
.pause-screen, .end-screen { background: radial-gradient(ellipse at center, rgba(6,10,12,0.72), rgba(2,4,5,0.94)); backdrop-filter: blur(9px); display: flex; align-items: center; justify-content: center; }
.pause-card, .end-card { width: min(520px, 88vw); background: linear-gradient(155deg, rgba(17,24,28,0.96), rgba(6,10,12,0.98)); border: 1px solid rgba(255,255,255,0.13); border-top: 2px solid var(--orange); padding: 34px 38px; box-shadow: 0 30px 120px #000; }
.menu-kicker { font-family: var(--mono); font-size: 9px; letter-spacing: 0.28em; color: var(--orange); }
.pause-card h2, .end-card h2 { margin: 10px 0 22px; font-size: 40px; letter-spacing: -0.01em; }
.pause-stats, .end-stats { display: flex; gap: 26px; margin-bottom: 26px; padding: 16px 0; border-top: 1px solid rgba(255,255,255,0.09); border-bottom: 1px solid rgba(255,255,255,0.09); }
.pause-stats div, .end-stats div { display: flex; flex-direction: column; gap: 3px; }
.pause-stats span, .end-stats span { font-family: var(--mono); font-size: 7px; letter-spacing: 0.18em; color: rgba(220,232,236,0.4); }
.pause-stats b, .end-stats b { font-family: var(--mono); font-size: 18px; color: #fff; }
.pause-card .deploy-button, .end-card .deploy-button { width: 100%; margin-top: 8px; }
.pause-card .ghost-button, .end-card .ghost-button { width: 100%; margin-top: 9px; height: 44px; }
.pause-hint { margin-top: 14px; text-align: center; font-family: var(--mono); font-size: 8px; color: rgba(220,232,236,0.34); }
.end-card { text-align: center; width: min(620px, 90vw); }
.end-card .menu-kicker { color: var(--red); }
.end-card h2 { font-size: 80px; line-height: 0.9; margin: 12px 0 10px; }
.end-card.win .menu-kicker { color: var(--orange); }
.end-card.win h2 { color: var(--orange); }
.end-sub { font-family: var(--mono); font-size: 11px; color: rgba(220,232,236,0.5); margin: 0 0 24px; }
.end-stats { justify-content: center; }
.end-actions { display: flex; gap: 10px; }
.end-actions .deploy-button { margin-top: 0; }
.end-actions .ghost-button { margin-top: 0; }

/* ---------- touch ---------- */
.touch-controls { position: absolute; inset: 0; z-index: 30; pointer-events: none; }
.move-stick { position: absolute; left: 24px; bottom: 112px; width: 112px; height: 112px; border: 1px solid rgba(255,255,255,0.18); border-radius: 50%; background: rgba(5,9,11,0.35); pointer-events: auto; }
.move-stick span { position: absolute; left: 50%; top: 50%; width: 44px; height: 44px; margin: -22px; border-radius: 50%; background: rgba(255,106,26,0.36); border: 1px solid rgba(255,106,26,0.8); }
.look-zone { position: absolute; right: 0; top: 0; width: 55%; height: 100%; pointer-events: auto; }
.fire-button { position: absolute; right: 28px; bottom: 126px; width: 82px; height: 82px; border-radius: 50%; border: 1px solid rgba(255,106,26,0.75); background: rgba(255,106,26,0.18); color: var(--orange); font-family: var(--display); font-weight: 700; font-size: 12px; letter-spacing: 0.12em; pointer-events: auto; }
.touch-small { position: absolute; right: 122px; bottom: 126px; height: 42px; padding: 0 14px; border: 1px solid rgba(255,255,255,0.2); background: rgba(5,9,11,0.45); color: rgba(238,245,247,0.7); font-family: var(--mono); font-size: 8px; pointer-events: auto; }
.ads-touch { right: 122px; bottom: 176px; }

@media (max-width: 900px) {
  .start-screen { padding: 22px 24px 20px; }
  .brief-panel { display: none; }
  .menu-main { padding-left: 0; }
  .menu-stats { margin-top: 26px; gap: 32px; }
  .menu-footer { flex-direction: column; align-items: flex-start; gap: 12px; }
  .classification { display: none; }
  .mission { width: 240px; left: 16px; top: 16px; }
  .objective-text { font-size: 13px; }
  .top-right { right: 14px; top: 14px; width: 200px; }
  .radar-panel { width: 118px; height: 118px; }
  .health-panel { left: 16px; bottom: 16px; width: 246px; }
  .ammo-panel { right: 16px; bottom: 16px; width: 220px; }
  .loadout, .control-hint, .build-tag { display: none; }
  .compass-wrap { top: 14px; width: 34vw; }
}
@media (max-width: 640px) {
  h1 { font-size: 60px; }
  .tagline { font-size: 10px; }
  .menu-stats { display: none; }
  .deploy-button { width: 210px; height: 54px; font-size: 14px; }
  .ghost-button { height: 54px; }
  .mission { width: 200px; }
  .mission-top { font-size: 6px; }
  .objective-text { font-size: 11px; }
  .wave-row { font-size: 6px; }
  .score-panel { width: 100%; padding: 6px 9px; }
  .score-item strong { font-size: 10px; }
  .radar-panel { width: 96px; height: 96px; }
  .top-right { width: 164px; }
  .health-panel { width: 210px; padding: 8px 11px; }
  .health-main strong { font-size: 26px; }
  .ammo-panel { width: 174px; padding: 8px 11px; }
  .mag { font-size: 30px; }
  .reserve { font-size: 11px; }
  .ammo-meta { gap: 7px; font-size: 6px; }
  .weapon-name { font-size: 6px; }
  .control-hint { display: none; }
  .end-card h2 { font-size: 60px; }
  .end-stats { gap: 14px; }
  .pause-card, .end-card { padding: 26px 24px; }
}

