import * as THREE from 'three';
import { rng, makeBulletHole, makeFlash, makeGlow, makeParticle } from './textures.js';

export class Effects {
  constructor(scene) {
    this.scene = scene;
    this.maxParticles = 900;
    this.particles = [];
    const geo = new THREE.BufferGeometry();
    const pos = new Float32Array(this.maxParticles * 3);
    const col = new Float32Array(this.maxParticles * 3);
    for (let i = 0; i < this.maxParticles; i++) {
      pos[i * 3 + 1] = -999;
      this.particles.push({ active: false, x: 0, y: -999, z: 0, vx: 0, vy: 0, vz: 0, life: 0, max: 1, gravity: 9, r: 1, g: 1, b: 1 });
    }
    geo.setAttribute('position', new THREE.BufferAttribute(pos, 3));
    geo.setAttribute('color', new THREE.BufferAttribute(col, 3));
    this.particleGeo = geo;
    this.particlePoints = new THREE.Points(geo, new THREE.PointsMaterial({
      size: 0.075, map: makeParticle(), vertexColors: true, transparent: true,
      blending: THREE.AdditiveBlending, depthWrite: false, alphaTest: 0.02, toneMapped: false
    }));
    this.particlePoints.frustumCulled = false;
    scene.add(this.particlePoints);

    this.tracerGeo = new THREE.CylinderGeometry(1, 1, 1, 6, 1, true);
    this.tracers = [];
    this.sprites = [];
    this.decals = [];
    this.casings = [];
    this.explosionFx = [];
    this.flashTex = makeFlash();
    this.glowTex = makeGlow();
    this.holeTex = makeBulletHole();
    this.casingMat = new THREE.MeshStandardMaterial({ color: 0xd7a64a, roughness: 0.28, metalness: 1.0 });
    this.casingGeo = new THREE.BoxGeometry(0.018, 0.018, 0.045);
    this.decalMat = new THREE.MeshBasicMaterial({ map: this.holeTex, transparent: true, depthWrite: false, polygonOffset: true, polygonOffsetFactor: -4, toneMapped: false });
    this._color = new THREE.Color();
    this._q = new THREE.Quaternion();
    this._y = new THREE.Vector3(0, 1, 0);
    this._dir = new THREE.Vector3();
  }

  spark(pos, color = 0xffb15a, count = 10, speed = 5, life = 0.55, gravity = 12) {
    this._color.setHex(color);
    for (let i = 0; i < count; i++) {
      const p = this.particles.find(p => !p.active);
      if (!p) return;
      p.active = true;
      p.x = pos.x; p.y = pos.y; p.z = pos.z;
      const a = Math.random() * Math.PI * 2;
      const e = rng(-0.4, 1);
      const sp = speed * rng(0.35, 1);
      p.vx = Math.cos(a) * sp * Math.cos(e);
      p.vz = Math.sin(a) * sp * Math.cos(e);
      p.vy = Math.sin(e) * sp + rng(0, 2);
      p.life = p.max = life * rng(0.5, 1.2);
      p.gravity = gravity;
      p.r = this._color.r; p.g = this._color.g; p.b = this._color.b;
    }
  }

  tracer(from, to, color = 0xffc27a, thickness = 0.009, life = 0.075) {
    const dir = this._dir.subVectors(to, from);
    const len = dir.length();
    if (len < 0.1) return;
    dir.normalize();
    const mat = new THREE.MeshBasicMaterial({ color, transparent: true, opacity: 0.95, blending: THREE.AdditiveBlending, depthWrite: false, toneMapped: false });
    const mesh = new THREE.Mesh(this.tracerGeo, mat);
    mesh.position.copy(from).addScaledVector(dir, len / 2);
    this._q.setFromUnitVectors(this._y, dir);
    mesh.quaternion.copy(this._q);
    mesh.scale.set(thickness, len, thickness);
    mesh.frustumCulled = false;
    this.scene.add(mesh);
    this.tracers.push({ mesh, life, max: life });
  }

  flash(pos, color = 0xffc070, scale = 0.5, life = 0.055) {
    const mat = new THREE.SpriteMaterial({ map: this.flashTex, color, transparent: true, opacity: 1, blending: THREE.AdditiveBlending, depthWrite: false, depthTest: true, toneMapped: false });
    const sprite = new THREE.Sprite(mat);
    sprite.position.copy(pos);
    sprite.scale.set(scale, scale, 1);
    this.scene.add(sprite);
    this.sprites.push({ sprite, life, max: life, startScale: scale });
  }

  impact(pos, normal, color = 0xffa25a, kind = 'metal') {
    this.spark(pos, color, kind === 'metal' ? 13 : 9, 6.5, 0.55, 13);
    this.flash(pos, color, 0.3, 0.045);
    const mesh = new THREE.Mesh(new THREE.PlaneGeometry(0.15, 0.15), this.decalMat.clone());
    mesh.position.copy(pos).addScaledVector(normal, 0.012);
    mesh.lookAt(pos.clone().add(normal));
    mesh.renderOrder = 3;
    this.scene.add(mesh);
    this.decals.push({ mesh, life: 12, max: 12 });
    if (this.decals.length > 46) {
      const old = this.decals.shift();
      this.scene.remove(old.mesh);
      old.mesh.geometry.dispose();
      old.mesh.material.dispose();
    }
  }

  casing(pos, direction) {
    const mesh = new THREE.Mesh(this.casingGeo, this.casingMat);
    mesh.position.copy(pos);
    mesh.rotation.set(rng(0, 3), rng(0, 3), rng(0, 3));
    mesh.castShadow = true;
    this.scene.add(mesh);
    this.casings.push({
      mesh, life: 2.2,
      vx: direction.x * rng(1.5, 3) + rng(-1, 1),
      vy: rng(2, 4), vz: direction.z * rng(1.5, 3) + rng(-1, 1),
      spin: rng(-12, 12)
    });
  }

  explosion(pos, radius = 6.5) {
    const sphere = new THREE.Mesh(
      new THREE.IcosahedronGeometry(1, 2),
      new THREE.MeshBasicMaterial({ color: 0xffb05a, transparent: true, opacity: 0.9, blending: THREE.AdditiveBlending, depthWrite: false, toneMapped: false })
    );
    sphere.position.copy(pos);
    sphere.scale.setScalar(0.4);
    this.scene.add(sphere);
    const ring = new THREE.Mesh(
      new THREE.RingGeometry(0.8, 1.1, 40),
      new THREE.MeshBasicMaterial({ color: 0xffc98a, transparent: true, opacity: 0.8, side: THREE.DoubleSide, blending: THREE.AdditiveBlending, depthWrite: false, toneMapped: false })
    );
    ring.position.copy(pos);
    ring.position.y = 0.08;
    ring.rotation.x = -Math.PI / 2;
    this.scene.add(ring);
    const light = new THREE.PointLight(0xff8a3a, 90, radius * 4, 1.6);
    light.position.copy(pos).add(new THREE.Vector3(0, 1, 0));
    this.scene.add(light);
    this.spark(pos, 0xffb35a, 80, 15, 1.15, 13);
    this.spark(pos, 0xffe8b0, 28, 9, 0.75, 8);
    this.flash(pos, 0xffa040, 5.5, 0.22);
    this.explosionFx.push({ sphere, ring, light, life: 0.85, max: 0.85, radius });
  }

  update(dt) {
    const pos = this.particleGeo.attributes.position.array;
    const col = this.particleGeo.attributes.color.array;
    for (let i = 0; i < this.maxParticles; i++) {
      const p = this.particles[i];
      if (!p.active) continue;
      p.life -= dt;
      if (p.life <= 0) {
        p.active = false;
        pos[i * 3 + 1] = -999;
        continue;
      }
      p.vy -= p.gravity * dt;
      p.x += p.vx * dt; p.y += p.vy * dt; p.z += p.vz * dt;
      if (p.y < 0.03) { p.y = 0.03; p.vy *= -0.25; p.vx *= 0.65; p.vz *= 0.65; }
      pos[i * 3] = p.x; pos[i * 3 + 1] = p.y; pos[i * 3 + 2] = p.z;
      const f = Math.max(0, p.life / p.max);
      col[i * 3] = p.r * f; col[i * 3 + 1] = p.g * f; col[i * 3 + 2] = p.b * f;
    }
    this.particleGeo.attributes.position.needsUpdate = true;
    this.particleGeo.attributes.color.needsUpdate = true;

    for (let i = this.tracers.length - 1; i >= 0; i--) {
      const t = this.tracers[i];
      t.life -= dt;
      if (t.life <= 0) {
        this.scene.remove(t.mesh);
        t.mesh.material.dispose();
        this.tracers.splice(i, 1);
      } else {
        t.mesh.material.opacity = 0.95 * (t.life / t.max);
      }
    }

    for (let i = this.sprites.length - 1; i >= 0; i--) {
      const s = this.sprites[i];
      s.life -= dt;
      if (s.life <= 0) {
        this.scene.remove(s.sprite);
        s.sprite.material.dispose();
        this.sprites.splice(i, 1);
      } else {
        const f = s.life / s.max;
        s.sprite.material.opacity = f;
        const sc = s.startScale * (1 + (1 - f) * 0.6);
        s.sprite.scale.set(sc, sc, 1);
      }
    }

    for (let i = this.decals.length - 1; i >= 0; i--) {
      const d = this.decals[i];
      d.life -= dt;
      if (d.life <= 0) {
        this.scene.remove(d.mesh);
        d.mesh.geometry.dispose();
        d.mesh.material.dispose();
        this.decals.splice(i, 1);
      } else if (d.life < 2) {
        d.mesh.material.opacity = d.life / 2;
      }
    }

    for (let i = this.casings.length - 1; i >= 0; i--) {
      const c = this.casings[i];
      c.life -= dt;
      if (c.life <= 0) {
        this.scene.remove(c.mesh);
        this.casings.splice(i, 1);
        continue;
      }
      c.vy -= 15 * dt;
      c.mesh.position.x += c.vx * dt;
      c.mesh.position.y += c.vy * dt;
      c.mesh.position.z += c.vz * dt;
      c.mesh.rotation.x += c.spin * dt;
      c.mesh.rotation.z += c.spin * 0.6 * dt;
      if (c.mesh.position.y < 0.02) {
        c.mesh.position.y = 0.02;
        c.vy *= -0.45;
        c.vx *= 0.7; c.vz *= 0.7;
        if (Math.abs(c.vy) < 0.25) c.vy = 0;
      }
    }

    for (let i = this.explosionFx.length - 1; i >= 0; i--) {
      const e = this.explosionFx[i];
      e.life -= dt;
      if (e.life <= 0) {
        this.scene.remove(e.sphere); this.scene.remove(e.ring); this.scene.remove(e.light);
        e.sphere.geometry.dispose(); e.sphere.material.dispose();
        e.ring.geometry.dispose(); e.ring.material.dispose();
        this.explosionFx.splice(i, 1);
        continue;
      }
      const f = e.life / e.max;
      const grow = 1 - f;
      e.sphere.scale.setScalar(0.4 + grow * e.radius);
      e.sphere.material.opacity = f * 0.8;
      e.ring.scale.setScalar(0.5 + grow * e.radius * 1.4);
      e.ring.material.opacity = f * 0.75;
      e.light.intensity = 90 * f * f;
    }
  }
}

import * as THREE from 'three';
import { makeFlash } from './textures.js';

function mat(color, rough, metal, extra = {}) {
  return new THREE.MeshStandardMaterial({ color, roughness: rough, metalness: metal, envMapIntensity: 1.15, ...extra });
}

const gunMetal = mat(0x2b3033, 0.28, 0.95);
const darkPoly = mat(0x171a1b, 0.62, 0.3);
const midPoly = mat(0x2b2e2c, 0.68, 0.15);
const steel = mat(0x656b6b, 0.2, 1.0);
const accent = mat(0xff6a1a, 0.35, 0.55, { emissive: 0xff3b00, emissiveIntensity: 1.2 });
const lens = new THREE.MeshBasicMaterial({ color: 0xff2a24, toneMapped: false });
const glass = new THREE.MeshStandardMaterial({ color: 0x0b1a20, roughness: 0.05, metalness: 1, envMapIntensity: 1.8 });
const glove = mat(0x1c1e1d, 0.88, 0.04);
const glovePad = mat(0x2c302e, 0.8, 0.08);
const sleeve = mat(0x3a3d36, 0.94, 0.02);

function box(w, h, d, x, y, z, material, parent, rot = null) {
  const mesh = new THREE.Mesh(new THREE.BoxGeometry(w, h, d), material);
  mesh.position.set(x, y, z);
  if (rot) mesh.rotation.set(rot[0] || 0, rot[1] || 0, rot[2] || 0);
  mesh.castShadow = false;
  mesh.receiveShadow = false;
  parent.add(mesh);
  return mesh;
}

function cyl(r1, r2, h, x, y, z, material, parent, rot = null, seg = 14) {
  const mesh = new THREE.Mesh(new THREE.CylinderGeometry(r1, r2, h, seg), material);
  mesh.position.set(x, y, z);
  if (rot) mesh.rotation.set(rot[0] || 0, rot[1] || 0, rot[2] || 0);
  parent.add(mesh);
  return mesh;
}

function flashRig(group, x, y, z, scale) {
  const sprite = new THREE.Sprite(new THREE.SpriteMaterial({
    map: makeFlash(), color: 0xffc47a, transparent: true, opacity: 1,
    blending: THREE.AdditiveBlending, depthWrite: false, depthTest: false, toneMapped: false
  }));
  sprite.position.set(x, y, z);
  sprite.scale.set(scale, scale, 1);
  sprite.visible = false;
  sprite.renderOrder = 20;
  group.add(sprite);
  const light = new THREE.PointLight(0xffa050, 0, 6, 2);
  light.position.set(x, y, z + 0.1);
  group.add(light);
  return { sprite, light };
}

function hand(parent, side = 1) {
  // side 1 = right hand / -1 = left hand
  const g = new THREE.Group();
  g.position.set(side * 0.035, -0.105, side > 0 ? 0.045 : -0.36);
  parent.add(g);
  box(0.072, 0.11, 0.095, 0, 0, 0, glove, g, [0.1, 0, side * 0.06]);
  box(0.078, 0.028, 0.075, 0, -0.056, 0.015, glovePad, g, [0.1, 0, 0]);
  // fingers wrapping
  for (let i = 0; i < 3; i++) box(0.02, 0.052, 0.026, side * (0.008 + i * 0.021), 0.01, 0.053, glovePad, g, [0.1, 0, 0]);
  // thumb
  box(0.022, 0.07, 0.028, side * -0.04, 0.03, 0.02, glove, g, [0.2, 0, side * -0.6]);
  // forearm
  const sleeveMesh = box(0.085, 0.09, 0.28, side * 0.015, -0.045, 0.17, sleeve, g, [0.08, 0, 0]);
  sleeveMesh.scale.z = 1;
  return g;
}

export function createRifle() {
  const root = new THREE.Group();
  const model = new THREE.Group();
  root.add(model);

  // receiver
  box(0.085, 0.105, 0.44, 0, 0, -0.11, gunMetal, model);
  box(0.074, 0.07, 0.36, 0, -0.02, -0.12, midPoly, model);
  box(0.09, 0.022, 0.3, 0, 0.056, -0.13, darkPoly, model);
  // rail
  box(0.05, 0.018, 0.44, 0, 0.079, -0.08, steel, model);
  for (let i = 0; i < 9; i++) box(0.054, 0.01, 0.013, 0, 0.092, -0.26 + i * 0.048, darkPoly, model);
  // handguard
  box(0.077, 0.082, 0.29, 0, 0.006, -0.45, midPoly, model);
  box(0.083, 0.018, 0.29, 0, 0.051, -0.45, darkPoly, model);
  for (let i = 0; i < 6; i++) box(0.087, 0.009, 0.02, 0, 0.01, -0.56 + i * 0.042, darkPoly, model);
  // barrel
  cyl(0.017, 0.017, 0.42, 0, 0.008, -0.64, gunMetal, model, [Math.PI / 2, 0, 0]);
  cyl(0.026, 0.03, 0.1, 0, 0.008, -0.86, steel, model, [Math.PI / 2, 0, 0]);
  for (let i = 0; i < 3; i++) box(0.055, 0.018, 0.012, 0, 0.008, -0.89 + i * 0.022, darkPoly, model);
  // gas block + front sight
  box(0.05, 0.055, 0.06, 0, 0.05, -0.58, gunMetal, model);
  box(0.026, 0.06, 0.024, 0, 0.085, -0.58, darkPoly, model);
  // stock
  box(0.07, 0.088, 0.2, 0, -0.002, 0.19, darkPoly, model, [-0.04, 0, 0]);
  box(0.055, 0.11, 0.055, 0, -0.02, 0.29, midPoly, model);
  box(0.064, 0.03, 0.13, 0, 0.045, 0.18, darkPoly, model);
  // pistol grip
  box(0.058, 0.14, 0.07, 0, -0.115, 0.055, darkPoly, model, [0.25, 0, 0]);
  box(0.05, 0.03, 0.055, 0, -0.19, 0.085, midPoly, model, [0.25, 0, 0]);
  // trigger guard
  box(0.012, 0.055, 0.105, 0.04, -0.072, -0.035, gunMetal, model);
  box(0.064, 0.014, 0.1, 0, -0.102, -0.035, gunMetal, model);
  // magazine
  box(0.055, 0.17, 0.105, 0, -0.14, -0.085, darkPoly, model, [0.07, 0, 0]);
  box(0.058, 0.028, 0.11, 0, -0.225, -0.075, midPoly, model, [0.07, 0, 0]);
  // optic
  box(0.052, 0.028, 0.11, 0, 0.105, -0.12, gunMetal, model);
  cyl(0.031, 0.031, 0.16, 0, 0.145, -0.12, gunMetal, model, [Math.PI / 2, 0, 0]);
  cyl(0.027, 0.027, 0.012, 0, 0.145, -0.202, lens, model, [Math.PI / 2, 0, 0]);
  cyl(0.024, 0.024, 0.01, 0, 0.145, -0.198, glass, model, [Math.PI / 2, 0, 0]);
  box(0.022, 0.02, 0.04, 0.035, 0.155, -0.09, steel, model);
  // flashlight
  cyl(0.022, 0.024, 0.1, -0.052, 0.015, -0.4, gunMetal, model, [Math.PI / 2, 0, 0]);
  cyl(0.019, 0.019, 0.006, -0.052, 0.015, -0.453, new THREE.MeshBasicMaterial({ color: 0xfff0c0, toneMapped: false }), model, [Math.PI / 2, 0, 0]);
  // side accent
  box(0.012, 0.018, 0.16, 0.044, 0.012, -0.12, accent, model);
  box(0.012, 0.018, 0.09, -0.044, 0.012, -0.44, accent, model);
  // charging handle
  box(0.04, 0.032, 0.05, 0.045, 0.042, 0.02, steel, model);
  // hands
  hand(model, 1);
  hand(model, -1);

  const muzzle = new THREE.Object3D();
  muzzle.position.set(0, 0.008, -0.925);
  root.add(muzzle);
  const eject = new THREE.Object3D();
  eject.position.set(0.06, 0.03, -0.04);
  root.add(eject);
  const { sprite, light } = flashRig(root, 0, 0.01, -0.94, 0.55);

  root.userData.muzzleFlash = sprite;
  root.userData.flashLight = light;
  root.userData.muzzle = muzzle;
  root.userData.eject = eject;
  return root;
}

export function createPistol() {
  const root = new THREE.Group();
  const model = new THREE.Group();
  root.add(model);

  box(0.062, 0.075, 0.3, 0, 0.015, -0.08, gunMetal, model);
  box(0.058, 0.05, 0.24, 0, -0.02, -0.06, darkPoly, model);
  box(0.064, 0.018, 0.25, 0, 0.055, -0.075, steel, model);
  for (let i = 0; i < 5; i++) box(0.058, 0.012, 0.014, 0, 0.067, -0.17 + i * 0.045, darkPoly, model);
  // barrel
  cyl(0.018, 0.018, 0.21, 0, 0.018, -0.28, gunMetal, model, [Math.PI / 2, 0, 0]);
  cyl(0.022, 0.022, 0.028, 0, 0.018, -0.39, steel, model, [Math.PI / 2, 0, 0]);
  // grip
  box(0.058, 0.17, 0.085, 0, -0.115, 0.04, darkPoly, model, [0.18, 0, 0]);
  for (let i = 0; i < 4; i++) box(0.061, 0.018, 0.05, 0, -0.08 - i * 0.032, 0.055 + i * 0.008, midPoly, model, [0.18, 0, 0]);
  box(0.05, 0.028, 0.08, 0, -0.205, 0.07, gunMetal, model, [0.18, 0, 0]);
  // trigger guard
  box(0.01, 0.05, 0.08, 0.032, -0.06, -0.01, gunMetal, model);
  box(0.052, 0.012, 0.08, 0, -0.087, -0.01, gunMetal, model);
  // sights
  box(0.032, 0.018, 0.018, 0, 0.075, 0.045, darkPoly, model);
  box(0.03, 0.02, 0.016, 0, 0.078, -0.21, darkPoly, model);
  // accent plate
  box(0.01, 0.018, 0.1, 0.034, -0.01, -0.07, accent, model);
  // hands
  hand(model, 1);
  const off = hand(model, -1);
  off.position.set(-0.055, -0.135, -0.02);
  off.rotation.z = -0.35;

  const muzzle = new THREE.Object3D();
  muzzle.position.set(0, 0.018, -0.4);
  root.add(muzzle);
  const eject = new THREE.Object3D();
  eject.position.set(0.045, 0.04, -0.04);
  root.add(eject);
  const { sprite, light } = flashRig(root, 0, 0.018, -0.415, 0.34);
  root.userData.muzzleFlash = sprite;
  root.userData.flashLight = light;
  root.userData.muzzle = muzzle;
  root.userData.eject = eject;
  return root;
}

import * as THREE from 'three';
import { clamp, rng } from './textures.js';

const _v1 = new THREE.Vector3();
const _v2 = new THREE.Vector3();
const _ray = new THREE.Raycaster();
const _q = new THREE.Quaternion();

function makeMat(color, roughness, metalness, extra = {}) {
  return new THREE.MeshStandardMaterial({ color, roughness, metalness, envMapIntensity: 0.9, ...extra });
}

function meshBox(w, h, d, x, y, z, material, parent) {
  const m = new THREE.Mesh(new THREE.BoxGeometry(w, h, d), material);
  m.position.set(x, y, z);
  m.castShadow = true;
  m.receiveShadow = true;
  parent.add(m);
  return m;
}

export class Enemy {
  constructor({ scene, effects, audio, game, position, boss = false, wave = 1 }) {
    this.scene = scene;
    this.effects = effects;
    this.audio = audio;
    this.game = game;
    this.boss = boss;
    this.wave = wave;
    this.root = new THREE.Group();
    this.root.position.copy(position);
    this.visual = new THREE.Group();
    this.root.add(this.visual);
    scene.add(this.root);

    this.maxHealth = boss ? 900 : Math.round(95 + wave * 7);
    this.health = this.maxHealth;
    this.speed = boss ? 2.7 : rng(3.8, 5.2);
    this.preferredNear = boss ? 11 : rng(7, 13);
    this.preferredFar = boss ? 23 : rng(15, 24);
    this.dead = false;
    this.finished = false;
    this.deathT = 0;
    this.deathDir = Math.random() < 0.5 ? 1 : -1;
    this.spawnT = 0.9;
    this.flashTime = 0;
    this.fireCooldown = rng(1.4, 2.8);
    this.burstLeft = 0;
    this.burstTimer = 0;
    this.strafeDir = Math.random() < 0.5 ? -1 : 1;
    this.strafeTimer = rng(1, 2.5);
    this.losTimer = 0;
    this.canSee = true;
    this.animPhase = Math.random() * 10;
    this.moveAmount = 0;
    this.summoned66 = false;
    this.summoned33 = false;
    this.age = 0;
    this.hitMeshes = [];
    this.flashMats = [];

    this.buildModel();
    this.buildHealthBar();
    this.root.scale.setScalar(this.spawnT > 0 ? 0.01 : 1);
    this.visual.scale.setScalar(boss ? 1.5 : rng(0.94, 1.06));
    this.spawnT = 0.9;
    this.root.traverse(o => { if (o.isMesh) o.frustumCulled = false; });
  }

  buildModel() {
    const armorColor = this.boss ? 0x301418 : 0x242a2c;
    const plateColor = this.boss ? 0x581d22 : 0x343b3d;
    this.armor = makeMat(armorColor, 0.36, 0.85);
    this.plate = makeMat(plateColor, 0.42, 0.8);
    this.cloth = makeMat(0x111514, 0.94, 0.05);
    this.visor = makeMat(0x210304, 0.18, 0.4, { emissive: this.boss ? 0xff1020 : 0xff2b30, emissiveIntensity: 5.5 });
    this.accent = makeMat(this.boss ? 0x4f0c10 : 0x4a1c0a, 0.35, 0.6, { emissive: 0xff3a00, emissiveIntensity: this.boss ? 2 : 1.1 });
    this.flashMats = [this.armor, this.plate];

    const v = this.visual;
    // pelvis / belt
    meshBox(0.46, 0.24, 0.3, 0, 0.94, 0, this.cloth, v);
    meshBox(0.5, 0.09, 0.34, 0, 1.03, 0, this.plate, v);
    meshBox(0.08, 0.11, 0.1, 0.25, 0.92, 0.03, this.accent, v);

    // torso
    const torso = meshBox(0.62, 0.64, 0.36, 0, 1.32, 0, this.cloth, v);
    const chest = meshBox(0.66, 0.48, 0.42, 0, 1.42, 0.015, this.armor, v);
    meshBox(0.42, 0.18, 0.44, 0, 1.58, 0.02, this.plate, v);
    meshBox(0.3, 0.1, 0.035, 0, 1.4, 0.23, this.accent, v);
    meshBox(0.1, 0.22, 0.03, -0.19, 1.31, 0.23, this.plate, v);
    meshBox(0.1, 0.22, 0.03, 0.19, 1.31, 0.23, this.plate, v);
    // backpack
    meshBox(0.42, 0.46, 0.18, 0, 1.35, -0.26, this.armor, v);
    meshBox(0.3, 0.1, 0.1, 0, 1.52, -0.36, this.plate, v);
    // shoulders
    const shoulderL = meshBox(0.26, 0.24, 0.34, -0.43, 1.5, 0, this.plate, v);
    const shoulderR = meshBox(0.26, 0.24, 0.34, 0.43, 1.5, 0, this.plate, v);
    shoulderL.rotation.z = 0.12; shoulderR.rotation.z = -0.12;

    // head
    const headGroup = new THREE.Group();
    headGroup.position.set(0, 1.72, 0.02);
    v.add(headGroup);
    const head = meshBox(0.28, 0.3, 0.3, 0, 0.06, 0, this.armor, headGroup);
    meshBox(0.33, 0.14, 0.33, 0, 0.18, 0, this.plate, headGroup);
    meshBox(0.19, 0.065, 0.035, 0, 0.05, 0.16, this.visor, headGroup);
    meshBox(0.05, 0.14, 0.12, 0.17, 0.06, -0.02, this.plate, headGroup);
    meshBox(0.05, 0.14, 0.12, -0.17, 0.06, -0.02, this.plate, headGroup);

    // arms with pivots
    this.arms = [];
    for (const side of [-1, 1]) {
      const pivot = new THREE.Group();
      pivot.position.set(side * 0.4, 1.47, 0);
      v.add(pivot);
      const upper = meshBox(0.19, 0.34, 0.22, side * 0.03, -0.18, 0, this.armor, pivot);
      meshBox(0.21, 0.12, 0.24, side * 0.03, -0.34, 0, this.plate, pivot);
      const fore = meshBox(0.16, 0.34, 0.18, side * 0.06, -0.52, 0.01, this.cloth, pivot);
      meshBox(0.17, 0.1, 0.2, side * 0.06, -0.66, 0.02, this.plate, pivot);
      this.arms.push(pivot);
      this.hitMeshes.push(upper, fore);
    }

    // legs with pivots
    this.legs = [];
    for (const side of [-1, 1]) {
      const pivot = new THREE.Group();
      pivot.position.set(side * 0.18, 0.92, 0);
      v.add(pivot);
      const thigh = meshBox(0.22, 0.42, 0.26, 0, -0.2, 0, this.cloth, pivot);
      const shin = meshBox(0.18, 0.38, 0.21, 0, -0.57, 0.01, this.armor, pivot);
      meshBox(0.19, 0.12, 0.22, 0, -0.44, 0.06, this.plate, pivot);
      meshBox(0.22, 0.12, 0.34, 0, -0.78, 0.06, this.plate, pivot);
      this.legs.push(pivot);
      this.hitMeshes.push(thigh, shin);
    }

    // rifle
    const gun = new THREE.Group();
    gun.position.set(0.34, 1.2, 0.29);
    v.add(gun);
    meshBox(0.07, 0.1, 0.55, 0, 0, 0.1, this.armor, gun);
    meshBox(0.05, 0.06, 0.34, 0, 0.05, 0.24, this.plate, gun);
    meshBox(0.02, 0.02, 0.36, 0, 0.01, 0.5, this.armor, gun);
    meshBox(0.04, 0.07, 0.08, 0, -0.08, 0.06, this.cloth, gun);
    meshBox(0.03, 0.08, 0.1, 0, -0.06, 0.17, this.plate, gun);
    this.gun = gun;

    // muzzle marker
    this.muzzle = new THREE.Object3D();
    this.muzzle.position.set(0.34, 1.21, 0.88);
    v.add(this.muzzle);

    // boss extras
    if (this.boss) {
      for (const side of [-1, 1]) {
        meshBox(0.28, 0.32, 0.42, side * 0.46, 1.68, -0.02, this.plate, v);
        const pod = new THREE.Mesh(new THREE.CylinderGeometry(0.11, 0.12, 0.34, 10), this.accent);
        pod.position.set(side * 0.56, 1.62, 0.16);
        pod.rotation.x = Math.PI / 2;
        v.add(pod);
      }
      const core = new THREE.Mesh(new THREE.IcosahedronGeometry(0.15, 1), this.visor);
      core.position.set(0, 1.38, 0.23);
      v.add(core);
      meshBox(0.34, 0.08, 0.06, 0, 1.79, 0.17, this.accent, v);
      this.core = core;
    }

    // register hitboxes
    for (const m of this.hitMeshes) {
      m.userData.enemy = this;
      m.userData.part = 'body';
      this.game.enemyShootables.push(m);
    }
    head.userData.enemy = this;
    head.userData.part = 'head';
    this.game.enemyShootables.push(head);
    this.head = head;
    torso.userData.enemy = this;
    torso.userData.part = 'body';
    this.game.enemyShootables.push(torso);
  }

  buildHealthBar() {
    this.hpCanvas = document.createElement('canvas');
    this.hpCanvas.width = 256;
    this.hpCanvas.height = 24;
    this.hpTex = new THREE.CanvasTexture(this.hpCanvas);
    this.hpTex.colorSpace = THREE.SRGBColorSpace;
    this.hpSprite = new THREE.Sprite(new THREE.SpriteMaterial({ map: this.hpTex, transparent: true, depthTest: false, depthWrite: false, toneMapped: false }));
    this.hpSprite.position.y = this.boss ? 4.4 : 2.22;
    this.hpSprite.scale.set(this.boss ? 2.8 : 1.15, this.boss ? 0.22 : 0.09, 1);
    this.hpSprite.visible = this.boss;
    this.hpSprite.renderOrder = 10;
    this.root.add(this.hpSprite);
    this.drawHealthBar(1);
  }

  drawHealthBar(ratio) {
    const ctx = this.hpCanvas.getContext('2d');
    const w = this.hpCanvas.width, h = this.hpCanvas.height;
    ctx.clearRect(0, 0, w, h);
    ctx.fillStyle = 'rgba(0,0,0,0.6)';
    ctx.fillRect(0, 4, w, h - 8);
    ctx.fillStyle = this.boss ? '#ff2538' : '#ff8b3d';
    ctx.fillRect(2, 6, (w - 4) * clamp(ratio, 0, 1), h - 12);
    ctx.strokeStyle = 'rgba(255,255,255,0.2)';
    ctx.lineWidth = 2;
    ctx.strokeRect(1, 5, w - 2, h - 10);
    this.hpTex.needsUpdate = true;
  }

  hit(damage, part, point) {
    if (this.dead || this.spawnT > 0) return { killed: false, headshot: false };
    const headshot = part === 'head';
    const mult = headshot ? 3 : part === 'leg' ? 0.72 : 1;
    this.health -= damage * mult;
    this.flashTime = 0.08;
    this.hpSprite.visible = true;
    this.drawHealthBar(this.health / this.maxHealth);
    this.effects.spark(point, this.boss ? 0xff3322 : 0xffb266, headshot ? 16 : 8, 5, 0.4, 10);
    if (this.health <= 0) {
      this.die(headshot);
      return { killed: true, headshot };
    }
    return { killed: false, headshot };
  }

  die(headshot) {
    if (this.dead) return;
    this.dead = true;
    this.deathT = 0;
    this.deathDir = Math.random() < 0.5 ? 1 : -1;
    this.hpSprite.visible = false;
    this.visor.emissiveIntensity = 0.15;
    this.root.updateMatrixWorld(true);
    _v1.set(this.root.position.x, this.root.position.y + 1.4, this.root.position.z);
    this.effects.spark(_v1, 0xffa040, this.boss ? 70 : 26, this.boss ? 12 : 6, 0.9, 12);
    if (this.boss) this.effects.explosion(_v1, 4);
    for (let i = this.game.enemyShootables.length - 1; i >= 0; i--) {
      if (this.game.enemyShootables[i].userData.enemy === this) this.game.enemyShootables.splice(i, 1);
    }
    this.game.onEnemyKilled(this, headshot);
  }

  update(dt, time) {
    this.age += dt;
    if (this.finished) return;

    if (this.dead) {
      this.deathT += dt;
      const t = clamp(this.deathT / 0.7, 0, 1);
      const ease = t * t * (3 - 2 * t);
      this.visual.rotation.z = ease * this.deathDir * 1.45;
      this.visual.rotation.x = ease * 0.18;
      this.visual.position.y = -ease * 0.45;
      if (this.boss) {
        this.visual.position.y = -ease * 0.2;
        this.visual.rotation.z = ease * this.deathDir * 0.6;
      }
      if (this.deathT > 2.4) {
        this.finished = true;
        this.scene.remove(this.root);
        this.dispose();
      }
      return;
    }

    if (this.spawnT > 0) {
      this.spawnT -= dt;
      const p = 1 - clamp(this.spawnT / 0.9, 0, 1);
      this.root.scale.setScalar(0.01 + (0.99 * p));
      return;
    }
    this.root.scale.setScalar(1);
    this.root.updateMatrixWorld(true);

    if (this.flashTime > 0) {
      this.flashTime -= dt;
      const on = this.flashTime > 0;
      for (const m of this.flashMats) m.emissive.setHex(on ? 0x7a1f0c : 0x000000);
      if (!on) this.visor.emissiveIntensity = 5.5;
    }

    const player = this.game.player;
    const px = player.pos.x, pz = player.pos.z;
    const dx = px - this.root.position.x;
    const dz = pz - this.root.position.z;
    const dist = Math.hypot(dx, dz);
    const nx = dx / (dist || 1), nz = dz / (dist || 1);

    // face player
    _v1.set(px, this.root.position.y, pz);
    this.root.lookAt(_v1);

    if (player.dead) return;

    // line of sight
    this.losTimer -= dt;
    if (this.losTimer <= 0) {
      this.losTimer = 0.28 + Math.random() * 0.18;
      _v1.set(this.root.position.x, 1.5, this.root.position.z);
      _v2.set(player.pos.x, player.eyeHeight + 0.1, player.pos.z);
      const targetDist = _v1.distanceTo(_v2);
      const dir = _v2.clone().sub(_v1).normalize();
      _ray.set(_v1, dir);
      _ray.far = targetDist;
      const hits = _ray.intersectObjects(this.game.worldShootables, false);
      this.canSee = hits.length === 0 || hits[0].distance >= targetDist - 0.4;
    }

    // strafing logic
    this.strafeTimer -= dt;
    if (this.strafeTimer <= 0) {
      this.strafeTimer = rng(1.1, 2.8);
      this.strafeDir = Math.random() < 0.5 ? -1 : 1;
    }

    let mx = 0, mz = 0;
    if (this.canSee) {
      if (dist > this.preferredFar) { mx += nx; mz += nz; }
      else if (dist < this.preferredNear) { mx -= nx; mz -= nz; }
      else {
        mx += -nz * this.strafeDir * 0.72 + nx * 0.1;
        mz += nx * this.strafeDir * 0.72 + nz * 0.1;
      }
    } else {
      mx += nx; mz += nz;
    }
    const ml = Math.hypot(mx, mz);
    if (ml > 0.01) {
      mx /= ml; mz /= ml;
      const step = this.speed * dt;
      let moved = false;
      if (!this.game.blockedAt(this.root.position.x + mx * step, this.root.position.z, 0.55)) {
        this.root.position.x += mx * step; moved = true;
      }
      if (!this.game.blockedAt(this.root.position.x, this.root.position.z + mz * step, 0.55)) {
        this.root.position.z += mz * step; moved = true;
      }
      if (!moved) this.strafeDir *= -1;
      this.moveAmount = THREE.MathUtils.lerp(this.moveAmount, 1, dt * 6);
    } else {
      this.moveAmount = THREE.MathUtils.lerp(this.moveAmount, 0, dt * 8);
    }
    this.animPhase += dt * (4.5 + this.speed * 0.6) * this.moveAmount;
    const swing = Math.sin(this.animPhase) * 0.55 * this.moveAmount;
    if (this.legs) {
      this.legs[0].rotation.x = swing;
      this.legs[1].rotation.x = -swing;
    }
    if (this.arms) {
      this.arms[0].rotation.x = -0.55 + Math.sin(this.animPhase + 0.4) * 0.08;
      this.arms[1].rotation.x = -0.7 - Math.sin(this.animPhase + 0.4) * 0.05;
    }
    if (this.core) this.core.rotation.y += dt * 2;

    // shooting
    if (this.canSee) {
      if (this.burstLeft > 0) {
        this.burstTimer -= dt;
        if (this.burstTimer <= 0) {
          this.fireShot(dist);
          this.burstLeft--;
          this.burstTimer = this.boss ? 0.12 : 0.135;
        }
      } else {
        this.fireCooldown -= dt;
        if (this.fireCooldown <= 0) {
          this.burstLeft = this.boss ? 7 : Math.floor(rng(3, 6));
          this.burstTimer = 0;
          this.fireCooldown = this.boss ? rng(1.2, 1.8) : rng(1.7, 3.2);
        }
      }
    }

    if (this.boss) {
      const ratio = this.health / this.maxHealth;
      if (!this.summoned66 && ratio <= 0.66) { this.summoned66 = true; this.game.spawnMinions(2, this.root.position); }
      if (!this.summoned33 && ratio <= 0.33) { this.summoned33 = true; this.game.spawnMinions(3, this.root.position); }
    }
  }

  fireShot(dist) {
    const player = this.game.player;
    if (player.dead) return;
    this.muzzle.getWorldPosition(_v1);
    _v2.set(player.pos.x + rng(-0.35, 0.35), player.eyeHeight + rng(-0.3, 0.2), player.pos.z + rng(-0.35, 0.35));
    const dir = _v2.clone().sub(_v1).normalize();
    const moving = Math.hypot(player.vel.x, player.vel.z);
    let chance = (this.boss ? 0.66 : 0.54) - dist * 0.0075 - moving * 0.02;
    if (player.crouching) chance -= 0.08;
    chance = clamp(chance, 0.12, 0.78);
    const hit = Math.random() < chance;
    if (hit) {
      this.game.damagePlayer(this.boss ? rng(8, 13) : rng(4.5, 8.5), this.root.position, true);
    } else {
      _v2.x += rng(-2.5, 2.5);
      _v2.y += rng(-0.5, 1.5);
    }
    this.effects.tracer(_v1.clone(), _v2, this.boss ? 0xff3045 : 0xffb060, this.boss ? 0.015 : 0.009, 0.09);
    this.effects.flash(_v1.clone(), this.boss ? 0xff3035 : 0xffb060, this.boss ? 0.6 : 0.36, 0.05);
    const pan = this.game.panFor(this.root.position);
    const vol = clamp(1.4 / (dist * 0.12 + 1), 0.1, 0.55);
    this.audio.enemyShot(vol, pan);
  }

  dispose() {
    this.root.traverse(o => {
      if (o.isMesh) {
        o.geometry?.dispose();
        if (o.material && !Array.isArray(o.material)) o.material.dispose();
      }
    });
  }
}

